insert into public.mcq_questions
  (id, course_slug, course_title, chapter_slug, topic, prompt, code, options, correct_option_id, explanation)
values
  ('mcq-java-what-is-java-and-how-it-runs-1v30nb3evvv', 'java', 'Java Programming', 'what-is-java-and-how-it-runs', 'oops', 'A `.class` file compiled on a Windows laptop is copied to a Linux server. What happens?', null, '[{"id":"a","text":"It fails to run — Java programs must be recompiled for each operating system."},{"id":"b","text":"It runs only if both machines use the same processor brand."},{"id":"c","text":"It runs unchanged, as long as the Linux machine has a JVM installed."},{"id":"d","text":"It runs, but only after being converted back to source code."}]'::jsonb, 'c', 'The `.class` file holds bytecode, not instructions for a specific OS or processor. Any machine with a JVM can load and run it — that''s the entire point of compiling to bytecode instead of compiling straight to native machine code the way C does.'),
  ('mcq-java-what-is-java-and-how-it-runs-20ivdwuz0sq', 'java', 'Java Programming', 'what-is-java-and-how-it-runs', 'oops', 'Which statement about JDK, JRE and JVM is correct?', null, '[{"id":"a","text":"The JDK contains the JRE, which contains the JVM."},{"id":"b","text":"The JVM contains the JRE, which contains the JDK."},{"id":"c","text":"JDK, JRE and JVM are three independent, unrelated tools you install separately."},{"id":"d","text":"The JRE is only needed for writing code, not running it."}]'::jsonb, 'a', 'It nests from largest to smallest: JDK (develop) ⊃ JRE (run + standard library) ⊃ JVM (execute bytecode). Installing the JDK gives you all three.'),
  ('mcq-java-what-is-java-and-how-it-runs-1t682go2697', 'java', 'Java Programming', 'what-is-java-and-how-it-runs', 'oops', 'Why is Java described as neither purely compiled nor purely interpreted?', null, '[{"id":"a","text":"Because Java code runs straight on the processor with no intermediate step, like a C program."},{"id":"b","text":"Because different companies build Java differently, so whether it is compiled or interpreted depends on the vendor."},{"id":"c","text":"Because Java has no compiler at all: the JVM reads the source text and interprets it directly."},{"id":"d","text":"Because javac compiles source to bytecode, and the JVM then interprets (and further optimises) that bytecode at run time."}]'::jsonb, 'd', 'Compilation happens once, ahead of time, producing bytecode. Interpretation (plus further just-in-time compilation for speed) happens every time that bytecode runs, inside the JVM. It''s a two-stage pipeline, which is exactly what makes it portable *and* reasonably fast.'),
  ('mcq-java-your-first-program-vjz3oojia0', 'java', 'Java Programming', 'your-first-program', 'oops', 'A file named `Register.java` contains `public class Attendance { ... }`. What happens?', null, '[{"id":"a","text":"It compiles and runs fine — file names and class names are unrelated in Java."},{"id":"b","text":"It fails to compile: a public class must be declared in a file with the same name."},{"id":"c","text":"It compiles but the JVM cannot find `main` inside it."},{"id":"d","text":"It compiles only if `Attendance` is declared `static`."}]'::jsonb, 'b', '`javac` enforces this rule at compile time, before the code is ever run: a `public` class named `Attendance` must live in `Attendance.java`, not `Register.java`.'),
  ('mcq-java-your-first-program-1rabkfybyww', 'java', 'Java Programming', 'your-first-program', 'oops', 'Why must `main` be declared `static`?', null, '[{"id":"a","text":"Because static methods run faster than non-static ones, and main has to start the program quickly."},{"id":"b","text":"Because every void method in a class is required by the compiler to also be static."},{"id":"c","text":"Purely a style convention that most programmers follow, with no technical reason behind it."},{"id":"d","text":"Because the JVM calls main before any object exists, and static members can be called without an object."}]'::jsonb, 'd', 'The JVM''s very first move is to call `main` — there is no object yet for it to call a non-static method on. `static` is exactly the keyword that means ''reachable without an object.'''),
  ('mcq-java-your-first-program-eguy049s1', 'java', 'Java Programming', 'your-first-program', 'oops', 'Given `System.out.print("A"); System.out.println("B"); System.out.println("C");` what is printed?', null, '[{"id":"a","text":"A\nB\nC"},{"id":"b","text":"AB\nC"},{"id":"c","text":"A B\nC"},{"id":"d","text":"ABC"}]'::jsonb, 'b', '`print("A")` writes A with no line break. `println("B")` continues on the same line — giving `AB` — then breaks the line. `println("C")` then writes C on its own new line.'),
  ('mcq-java-variables-and-data-types-11vfs2k5sfk', 'java', 'Java Programming', 'variables-and-data-types', 'oops', 'What happens when `int score;` is declared inside `main` and then printed without being assigned a value?', null, '[{"id":"a","text":"It prints 0, because Java gives every int variable the default value of zero."},{"id":"b","text":"It compiles and prints an unpredictable garbage value left over in memory."},{"id":"c","text":"It fails to compile: a local variable must be initialised before it is read."},{"id":"d","text":"It prints null, since an uninitialised variable holds no value at all."}]'::jsonb, 'c', 'Default values (0, false, null, ...) apply to fields of a class, not to local variables inside a method. A local variable read before assignment is a compile-time error in Java, by design.'),
  ('mcq-java-variables-and-data-types-1p8fpkwjmbq', 'java', 'Java Programming', 'variables-and-data-types', 'oops', 'Which declaration fails to compile?', null, '[{"id":"a","text":"double d = 3.14;"},{"id":"b","text":"byte b = 100;"},{"id":"c","text":"float f = 3.14;"},{"id":"d","text":"long big = 10000000000L;"}]'::jsonb, 'c', '`3.14` on its own is a `double` literal. Assigning a `double` to a `float` variable would lose precision, so Java requires an explicit `f` suffix (`3.14f`) or a cast — without it, this line does not compile.'),
  ('mcq-java-variables-and-data-types-8ynom0brce', 'java', 'Java Programming', 'variables-and-data-types', 'oops', 'What best describes a `String` variable in Java?', null, '[{"id":"a","text":"A ninth primitive type, which Java adds to the other eight for working with text."},{"id":"b","text":"A primitive type that Java sometimes treats specially, so that it is stored directly in the variable."},{"id":"c","text":"Exactly identical in behaviour to char, except that it can hold more than one character."},{"id":"d","text":"A reference type: the variable holds directions to a String object, not the characters themselves."}]'::jsonb, 'd', '`String` is `java.lang.String`, a class. A `String` variable is a reference — it points to where the actual character data lives — which is why it''s grouped with reference types, not the eight primitives.'),
  ('mcq-java-operators-t5tza88anu', 'java', 'Java Programming', 'operators', 'oops', 'What does `System.out.println(9 / 4);` print?', null, '[{"id":"a","text":"2"},{"id":"b","text":"2.25"},{"id":"c","text":"3"},{"id":"d","text":"2.0"}]'::jsonb, 'a', 'Both `9` and `4` are int literals, so `/` performs integer division: 4 goes into 9 twice, with a remainder discarded entirely. The result is `2`, not a rounded or decimal value.'),
  ('mcq-java-operators-23d3zrsuac5', 'java', 'Java Programming', 'operators', 'oops', 'In `boolean ok = (x != null) && (x.length() > 0);`, why does the order of the two checks matter?', null, '[{"id":"a","text":"Because Java evaluates the right side of && before the left, so the null check must come last."},{"id":"b","text":"It doesn''t matter, because Java always evaluates both sides of && before it decides the result."},{"id":"c","text":"Because && accepts method calls only on its right side, so the null check has to come first."},{"id":"d","text":"Because of short-circuiting: if x is null the left side is false, so x.length() is never evaluated."}]'::jsonb, 'd', '&& short-circuits left to right. If `x != null` is false, Java already knows the whole expression is false and skips `x.length() > 0` — which would otherwise throw a NullPointerException on a null x.'),
  ('mcq-java-operators-3v16c6cdng', 'java', 'Java Programming', 'operators', 'oops', 'What is the value of `result` after `int count = 4; int result = count++ + count;`?', null, '[{"id":"a","text":"10"},{"id":"b","text":"9"},{"id":"c","text":"4"},{"id":"d","text":"8"}]'::jsonb, 'b', '`count++` is post-increment: it evaluates to the *current* value of count (4) for use in the expression, and only afterwards increments count to 5. So the expression becomes `4 + 5 = 9`, and count ends at 5.'),
  ('mcq-java-input-and-output-tv40m88cbg', 'java', 'Java Programming', 'input-and-output', 'oops', 'A program calls `int n = sc.nextInt();` then immediately `String s = sc.nextLine();`. What does `s` usually contain?', null, '[{"id":"a","text":"An empty string — nextLine() reads the leftover newline left behind by nextInt()."},{"id":"b","text":"The same number that nextInt() just read, converted to text."},{"id":"c","text":"The next full line the user types after entering the number."},{"id":"d","text":"It throws an exception."}]'::jsonb, 'a', 'nextInt() consumes only the digits, not the Enter key press after them. The very next nextLine() immediately hits that leftover newline and returns everything up to it — which is nothing.'),
  ('mcq-java-input-and-output-c9ebx1mxu3', 'java', 'Java Programming', 'input-and-output', 'oops', 'What does `System.out.printf("%.2f%n", 3.14159);` print?', null, '[{"id":"a","text":"3.142"},{"id":"b","text":"3.14"},{"id":"c","text":"3.1"},{"id":"d","text":"3.14159"}]'::jsonb, 'b', '`%.2f` rounds the decimal to exactly 2 places after the point. 3.14159 rounds to 3.14 at two decimal places.'),
  ('mcq-java-input-and-output-1o84qccqaff', 'java', 'Java Programming', 'input-and-output', 'oops', 'Why might sc.next() be the wrong choice for reading someone''s full name?', null, '[{"id":"a","text":"next() can read only numbers, so any text such as a name makes it fail at run time."},{"id":"b","text":"next() reads only one word: it stops at the first space, so a name with a space is cut short."},{"id":"c","text":"next() and nextLine() behave identically, so using either one for a full name works the same."},{"id":"d","text":"next() requires the name to be typed inside quotes, otherwise it returns nothing at all."}]'::jsonb, 'b', 'next() reads up to the next whitespace character. "Meera Sharma" typed after a next() call would give back only "Meera" — nextLine() is needed to capture the whole line.'),
  ('mcq-java-type-casting-1p9hw9cfz9s', 'java', 'Java Programming', 'type-casting', 'oops', 'What does `System.out.println((int) 9.99);` print?', null, '[{"id":"a","text":"It fails to compile."},{"id":"b","text":"10"},{"id":"c","text":"9"},{"id":"d","text":"9.99"}]'::jsonb, 'c', 'Casting a double to int truncates the fractional part rather than rounding. 9.99 becomes 9.'),
  ('mcq-java-type-casting-2byfar2jvqa', 'java', 'Java Programming', 'type-casting', 'oops', 'Why does `double d = 42;` compile with no cast, while `int i = 42.0;` does not?', null, '[{"id":"a","text":"Because 42.0 is stored as a float, and a float can never be assigned to an int variable."},{"id":"b","text":"There is no real difference: Java inserts the needed conversion automatically in both statements."},{"id":"c","text":"Widening int to double is safe and automatic; narrowing double to int can lose the fraction."},{"id":"d","text":"Because Java only allows casting from int to double, and never lets a double be converted to an int."}]'::jsonb, 'c', 'Every whole number an int can hold fits exactly inside a double, so that direction is automatic. The reverse could silently drop a fractional part, so Java requires you to write `(int) 42.0` to acknowledge that.'),
  ('mcq-java-type-casting-17rfnlagdbi', 'java', 'Java Programming', 'type-casting', 'oops', '`byte b = (byte) 200;` — what does `b` hold, and why?', null, '[{"id":"a","text":"It fails to compile."},{"id":"b","text":"127, because Java clamps any out-of-range value to the maximum of the target type."},{"id":"c","text":"-56: 200 doesn''t fit in byte''s -128..127 range, so it wraps around; Java does not clamp."},{"id":"d","text":"200, because byte can actually hold values up to 255 when the number is cast explicitly."}]'::jsonb, 'c', 'byte''s range is -128 to 127. Casting 200 into it does not clamp to the nearest valid value — it wraps around using the same binary-overflow rule that turned 130 into -126 in this chapter''s example, landing on a different, still-valid-looking but wrong byte value.'),
  ('mcq-java-if-else-and-switch-1rm36t1zy5j', 'java', 'Java Programming', 'if-else-and-switch', 'oops', 'Given `int x = 70;` and the ladder `if (x >= 90) ... else if (x >= 60) ... else if (x >= 50) ... else ...`, which branch runs?', null, '[{"id":"a","text":"All three matching branches run, one after another, from the top down to the last match."},{"id":"b","text":"The x >= 50 branch, since 70 satisfies that condition as well."},{"id":"c","text":"The x >= 90 branch, because it is the first one written and so is checked first."},{"id":"d","text":"The x >= 60 branch, the first condition (top to bottom) that x satisfies."}]'::jsonb, 'd', 'The ladder stops at the first true condition. 70 fails >= 90, then satisfies >= 60 — that branch runs, and >= 50 (also technically true for 70) is never even checked.'),
  ('mcq-java-if-else-and-switch-150vh8smcnb', 'java', 'Java Programming', 'if-else-and-switch', 'oops', 'In a classic switch, what happens if a matching case has no `break` and isn''t the last case?', null, '[{"id":"a","text":"The switch silently jumps ahead to the default case, skipping every case in between."},{"id":"b","text":"It''s a compile error, because every case in a classic switch must end with break."},{"id":"c","text":"Execution falls through into the next case''s code, whether or not that case matches."},{"id":"d","text":"Nothing else runs, because Java stops automatically after the first matching case."}]'::jsonb, 'c', 'A classic switch, without an explicit break, continues executing the statements of the cases that follow, regardless of their labels, until it hits a break or the end of the switch.'),
  ('mcq-java-if-else-and-switch-1dxnekkeb7e', 'java', 'Java Programming', 'if-else-and-switch', 'oops', 'What is one real advantage of the switch expression (`->` form) over the classic switch?', null, '[{"id":"a","text":"It removes the need for a default case entirely, in every situation."},{"id":"b","text":"It supports more data types than the classic switch."},{"id":"c","text":"It does not fall through between cases, and can directly produce a value for assignment."},{"id":"d","text":"It runs faster at execution time."}]'::jsonb, 'c', 'Each arm of a switch expression is self-contained — no break needed, no accidental fall-through — and the whole switch can be used directly as an expression, e.g. assigned straight into a variable, as `season` is above.'),
  ('mcq-java-loops-20n8vg94i2i', 'java', 'Java Programming', 'loops', 'oops', 'How many times does `for (int i = 0; i < 5; i++) { ... }` run its body?', null, '[{"id":"a","text":"5 times"},{"id":"b","text":"It depends on i''s initial value at declaration."},{"id":"c","text":"6 times"},{"id":"d","text":"4 times"}]'::jsonb, 'a', 'i takes the values 0, 1, 2, 3, 4 — each satisfies i < 5, and 5 itself does not. That''s 5 iterations, a classic ''count from 0, stop before the limit'' pattern.'),
  ('mcq-java-loops-1pi4cmr1qm5', 'java', 'Java Programming', 'loops', 'oops', 'What is the key behavioural difference between while and do-while?', null, '[{"id":"a","text":"There is no real difference — they always produce identical results."},{"id":"b","text":"do-while checks its condition after running the body once; while checks before running the body at all."},{"id":"c","text":"while can use any condition; do-while can only use boolean variables, not expressions."},{"id":"d","text":"while loops cannot contain other loops; do-while loops can."}]'::jsonb, 'b', 'do-while is defined by checking after: the body always runs at least once, even if the condition is false from the very start — exactly what the `while (false)` example demonstrated.'),
  ('mcq-java-loops-wx2vuxzux1', 'java', 'Java Programming', 'loops', 'oops', 'What is wrong with `while (x > 0) { System.out.println(x); }` if x starts at 5 and is never changed inside the loop?', null, '[{"id":"a","text":"It prints the numbers 5 down to 1 automatically, like a for loop would."},{"id":"b","text":"It''s an infinite loop: the condition x > 0 never becomes false, since x is never updated."},{"id":"c","text":"It fails to compile because there''s no update expression."},{"id":"d","text":"Nothing — it prints 5 once and exits cleanly."}]'::jsonb, 'b', 'Unlike for, while has no built-in update step — if nothing inside the body changes x, the condition x > 0 stays true forever, and the loop never terminates.'),
  ('mcq-java-break-continue-and-nested-loops-rp6c7dol00', 'java', 'Java Programming', 'break-continue-and-nested-loops', 'oops', 'What does `for (int i = 1; i <= 5; i++) { if (i == 3) continue; System.out.print(i); }` print?', null, '[{"id":"a","text":"12"},{"id":"b","text":"1245"},{"id":"c","text":"12345"},{"id":"d","text":"124"}]'::jsonb, 'b', 'continue skips only the print for i == 3 — it does not stop the loop. i still takes every value 1 through 5, so the output is 1, 2, 4, 5 printed together as "1245".'),
  ('mcq-java-break-continue-and-nested-loops-12tp1dli543', 'java', 'Java Programming', 'break-continue-and-nested-loops', 'oops', 'In a nested loop building a pattern, what typically makes each row a different width?', null, '[{"id":"a","text":"Java automatically shrinks loops that are nested inside another loop."},{"id":"b","text":"The outer loop''s condition changes on every row automatically."},{"id":"c","text":"The inner loop''s upper bound depends on the outer loop''s current variable, e.g. `j <= i`."},{"id":"d","text":"Nested loops always produce the same width on every row; varying width needs an if statement."}]'::jsonb, 'c', 'The inner loop runs to its own bound every time — making that bound depend on the outer variable (as in `for (int j = 1; j <= i; j++)`) is exactly what makes the row''s length change as the outer loop advances.'),
  ('mcq-java-break-continue-and-nested-loops-o75wu5qr48', 'java', 'Java Programming', 'break-continue-and-nested-loops', 'oops', 'Why doesn''t a plain (unlabelled) `break` inside the inner loop of a nested pair stop the outer loop too?', null, '[{"id":"a","text":"break only works on while loops, not for loops, once they are nested inside another loop."},{"id":"b","text":"It''s a compile error to use break inside a nested loop at all, so a flag variable is required."},{"id":"c","text":"break always stops every loop it''s nested inside, without exception."},{"id":"d","text":"break only affects the innermost loop around it, unless a label names an outer loop."}]'::jsonb, 'd', 'By default, break (and continue) act on the nearest enclosing loop only. Reaching an outer loop requires a label on that outer loop and `break <label>;` — exactly the pattern shown with `break outer;` above.'),
  ('mcq-java-arrays-2auific1ri0', 'java', 'Java Programming', 'arrays', 'oops', 'Given `int[] a = {10, 20, 30};`, what does `a[a.length - 1]` give?', null, '[{"id":"a","text":"20"},{"id":"b","text":"It throws an exception."},{"id":"c","text":"10"},{"id":"d","text":"30"}]'::jsonb, 'd', 'a.length is 3. a.length - 1 is 2, the index of the last valid element in a 3-element array (indices 0, 1, 2). a[2] is 30.'),
  ('mcq-java-arrays-ufln3p9u4b', 'java', 'Java Programming', 'arrays', 'oops', 'What happens when you run `for (int m : marks) { m = m * 2; }` intending to double every element of marks in place?', null, '[{"id":"a","text":"It fails to compile, since a for-each loop variable cannot be reassigned inside the loop body."},{"id":"b","text":"It works exactly as intended, doubling every element of marks, because m refers to each slot in turn."},{"id":"c","text":"It compiles and runs, but marks is unchanged; m is a copy of each element, not the array slot itself."},{"id":"d","text":"It throws an exception at runtime, because the loop is modifying the array while it iterates."}]'::jsonb, 'c', 'The for-each loop hands you a fresh local copy of each element on every iteration. Reassigning that copy has no effect on the array itself — an indexed for loop (`marks[i] = marks[i] * 2;`) is required to actually modify the array.'),
  ('mcq-java-arrays-10qep15jvu6', 'java', 'Java Programming', 'arrays', 'oops', 'In `int[][] seating = {{1,2,3},{4,5,6}};`, what is `seating.length`?', null, '[{"id":"a","text":"It fails to compile."},{"id":"b","text":"6, the total number of elements"},{"id":"c","text":"2, the number of rows"},{"id":"d","text":"3, the length of one row"}]'::jsonb, 'c', 'seating is an array of arrays. Its own .length is the number of rows (2) — the outer array''s size. Each row''s own length (3, here) is a separate property, accessed as seating[row].length.'),
  ('mcq-java-strings-29mmpm8aj4t', 'java', 'Java Programming', 'strings', 'oops', '`String x = "cat"; String y = "cat"; String z = new String("cat");` — which comparison is false?', null, '[{"id":"a","text":"x == z"},{"id":"b","text":"x.equals(y)"},{"id":"c","text":"x.equals(z)"},{"id":"d","text":"x == y"}]'::jsonb, 'a', 'x and y are both literals, so the string pool gives them the same object — x == y is true. z is explicitly a new object via `new String(...)`, so x == z is false, even though the text is identical (which is exactly why x.equals(z) is true).'),
  ('mcq-java-strings-1rhu9207vv8', 'java', 'Java Programming', 'strings', 'oops', 'After `String s = "  hi  "; s.trim();` with no reassignment, what does s hold?', null, '[{"id":"a","text":"null, because trim() with no reassignment leaves the variable without a value."},{"id":"b","text":"\"hi\", because trim() removes the whitespace from s itself, even without reassignment."},{"id":"c","text":"It fails to compile, because the result of trim() is ignored and Java requires it to be used."},{"id":"d","text":"\"  hi  \", unchanged: trim() returned a new string that was never captured."}]'::jsonb, 'd', 'String is immutable — trim() cannot modify s in place, it can only return a new trimmed string. Since the result of s.trim() was discarded and not assigned back to s, s is exactly as it was.'),
  ('mcq-java-strings-fh8abcr7hq', 'java', 'Java Programming', 'strings', 'oops', 'What does `"programming".substring(3, 7)` evaluate to?', null, '[{"id":"a","text":"\"gramm\""},{"id":"b","text":"\"gram\""},{"id":"c","text":"\"rammi\""},{"id":"d","text":"\"ram\""}]'::jsonb, 'b', 'Indices: p=0,r=1,o=2,g=3,r=4,a=5,m=6,m=7,i=8... substring(3,7) starts at index 3 (''g'') and stops before index 7, covering indices 3,4,5,6 — g,r,a,m — giving "gram".'),
  ('mcq-java-stringbuilder-2zkjukmfz2', 'java', 'Java Programming', 'stringbuilder', 'oops', 'Why is `result = result + i;` inside a loop considered wasteful compared to `sb.append(i);`?', null, '[{"id":"a","text":"Because String is immutable, each + creates a whole new String object; StringBuilder changes one object in place."},{"id":"b","text":"It isn''t wasteful, because the compiler turns every + in a loop into the same code as append."},{"id":"c","text":"Because + works only on numbers, so each pass has to convert the strings to numbers and back."},{"id":"d","text":"Because StringBuilder is a primitive type, so it avoids creating any objects at all."}]'::jsonb, 'a', 'Every + on an immutable String builds a brand-new object containing the old content plus the addition, then discards the old one. StringBuilder''s append() instead grows the same underlying object, with no repeated copying.'),
  ('mcq-java-stringbuilder-1ktqwmrzmut', 'java', 'Java Programming', 'stringbuilder', 'oops', 'What does `new StringBuilder("cat").reverse().toString()` produce?', null, '[{"id":"a","text":"\"tac\""},{"id":"b","text":"A StringBuilder object, not a String"},{"id":"c","text":"\"cat\""},{"id":"d","text":"It fails to compile."}]'::jsonb, 'a', 'reverse() reverses "cat" in place to "tac", still inside the StringBuilder. toString() then converts that current content into a genuine String, "tac".'),
  ('mcq-java-stringbuilder-231k5vfqfmg', 'java', 'Java Programming', 'stringbuilder', 'oops', 'Which best describes StringBuilder compared to String?', null, '[{"id":"a","text":"Both are immutable; StringBuilder is simply faster at printing text to the console."},{"id":"b","text":"StringBuilder is mutable, so its methods change the same object; String''s methods always return a new one."},{"id":"c","text":"String and StringBuilder are one class under two names, kept apart only for old code."},{"id":"d","text":"StringBuilder can hold only numbers, which is why text still has to be stored in a String."}]'::jsonb, 'b', 'That mutability is the entire distinction and the entire reason StringBuilder exists: append, insert, delete, reverse and setCharAt all change the existing object directly, with no new object created per call.'),
  ('mcq-java-methods-h75jubxqgv', 'java', 'Java Programming', 'methods', 'oops', 'After `void increment(int n) { n = n + 1; } int x = 5; increment(x);`, what is x?', null, '[{"id":"a","text":"It depends on the JVM."},{"id":"b","text":"6"},{"id":"c","text":"It fails to compile."},{"id":"d","text":"5"}]'::jsonb, 'd', 'int is a primitive — its value is copied into the parameter n. Changing n inside the method changes only that local copy; the caller''s x is completely untouched, and remains 5.'),
  ('mcq-java-methods-5rokfmhxwe', 'java', 'Java Programming', 'methods', 'oops', '`void addOne(int[] arr) { arr[0] = arr[0] + 1; } int[] data = {5}; addOne(data);` — what is data[0] afterward?', null, '[{"id":"a","text":"6"},{"id":"b","text":"It fails to compile."},{"id":"c","text":"It depends on the JVM."},{"id":"d","text":"5"}]'::jsonb, 'a', 'The reference to the array is copied, but both the copy (arr) and the original (data) point at the same array object. arr[0] = arr[0] + 1 mutates that shared object directly, so the change is visible through data too — data[0] becomes 6.'),
  ('mcq-java-methods-qm373dx2jn', 'java', 'Java Programming', 'methods', 'oops', 'Which pair of method declarations is a valid overload of each other?', null, '[{"id":"a","text":"int calc(int a) and int calc(int b)"},{"id":"b","text":"int calc(int a, int b) and int calc(double a, double b)"},{"id":"c","text":"void calc(int a) and void calc(int a, int b) — invalid, because they must share a return type"},{"id":"d","text":"int calc(int a) and double calc(int a)"}]'::jsonb, 'b', 'Overloading requires different parameter types or counts — the return type alone never distinguishes an overload (ruling out the pair that differ only in return type), and a parameter''s *name* is irrelevant to its signature (ruling out the pair that differ only in parameter names). calc(int,int) and calc(double,double) genuinely differ in parameter type, so they''re a valid overload pair.'),
  ('mcq-java-recursion-basics-sdc8yvj5fc', 'java', 'Java Programming', 'recursion-basics', 'oops', 'What is the purpose of a base case in a recursive method?', null, '[{"id":"a","text":"It is needed only in methods that return void, since other methods stop once they return a value."},{"id":"b","text":"It''s the condition where the method returns a direct answer without calling itself, which stops the recursion."},{"id":"c","text":"It converts the recursive method into a loop automatically, which removes the need for the call stack."},{"id":"d","text":"It makes the method run faster by skipping the recursive calls whenever the input is large."}]'::jsonb, 'b', 'Without a base case (or with one the recursive calls never actually reach), the method keeps calling itself indefinitely, eventually exhausting the call stack — a StackOverflowError.'),
  ('mcq-java-recursion-basics-2ax3dh1nnia', 'java', 'Java Programming', 'recursion-basics', 'oops', 'For `int sumDigits(int n) { if (n == 0) return 0; return (n % 10) + sumDigits(n / 10); }`, what does sumDigits(123) return?', null, '[{"id":"a","text":"It never terminates."},{"id":"b","text":"1"},{"id":"c","text":"6"},{"id":"d","text":"123"}]'::jsonb, 'c', 'sumDigits(123) = 3 + sumDigits(12) = 3 + (2 + sumDigits(1)) = 3 + 2 + (1 + sumDigits(0)) = 3 + 2 + 1 + 0 = 6. Each call peels off the last digit (n % 10) and recurses on the rest (n / 10), which shrinks toward the base case n == 0.'),
  ('mcq-java-recursion-basics-16ucpb5jzf7', 'java', 'Java Programming', 'recursion-basics', 'oops', 'Why is the naive recursive Fibonacci shown in this chapter considered inefficient for larger n?', null, '[{"id":"a","text":"Because Java cannot recurse more than twice in a row, so deeper calls get silently skipped."},{"id":"b","text":"Because it has no base case, so the calls never stop until memory runs out."},{"id":"c","text":"Because it recomputes the same smaller Fibonacci values over and over, with no memory of earlier results."},{"id":"d","text":"Because fibonacci(n - 1) and fibonacci(n - 2) run at the same time and interfere with each other''s variables."}]'::jsonb, 'c', 'fibonacci(5)''s two branches both eventually call fibonacci(3), fibonacci(2), and so on, each recomputed independently from scratch rather than reused — the number of redundant calls grows quickly as n grows, which is a cost specific to this particular recursive formulation.'),
  ('mcq-java-classes-and-objects-10jsu317mp', 'java', 'Java Programming', 'classes-and-objects', 'oops', 'What is printed by `Student s = new Student(); System.out.println(s.marks);` with no assignment to marks?', null, '[{"id":"a","text":"0"},{"id":"b","text":"Garbage/unpredictable value"},{"id":"c","text":"It fails to compile."},{"id":"d","text":"null"}]'::jsonb, 'a', 'int fields default to 0 automatically when an object is created — Java never leaves a field undefined the way it leaves an unassigned local variable.'),
  ('mcq-java-classes-and-objects-2g4p25omvma', 'java', 'Java Programming', 'classes-and-objects', 'oops', '`Student a = new Student(); Student b = a; b.marks = 50;` — what is a.marks afterward?', null, '[{"id":"a","text":"0"},{"id":"b","text":"null"},{"id":"c","text":"50"},{"id":"d","text":"It fails to compile."}]'::jsonb, 'c', 'b = a copies the reference, not the object — a and b now point at the exact same Student. Changing marks through b changes the one shared object, so a.marks is also 50.'),
  ('mcq-java-classes-and-objects-1s19tuub399', 'java', 'Java Programming', 'classes-and-objects', 'oops', 'What does `new Student()` actually do?', null, '[{"id":"a","text":"Declares the Student class to the compiler for the first time, so it must come before other code."},{"id":"b","text":"Creates a new object in memory with default field values and returns a reference to it."},{"id":"c","text":"Nothing visible, until a field is assigned a value; only then is memory set aside."},{"id":"d","text":"Copies an existing Student object into a new place in memory, field by field."}]'::jsonb, 'b', 'new allocates memory for a fresh object, initialises its fields to their defaults, and gives back a reference you can store in a variable — the class itself was already defined separately.'),
  ('mcq-java-constructors-and-this-pr2xlqsqlt', 'java', 'Java Programming', 'constructors-and-this', 'oops', 'Inside a constructor, what does `this.rollNumber = rollNumber;` do if the parameter is also named rollNumber?', null, '[{"id":"a","text":"Nothing — it''s a no-op"},{"id":"b","text":"Fails to compile — duplicate names"},{"id":"c","text":"Assigns the parameter''s value to the object''s field"},{"id":"d","text":"Assigns the field''s old value back to the parameter"}]'::jsonb, 'c', 'this.rollNumber refers to the field on the object being built; plain rollNumber (on the right) refers to the parameter. This line correctly copies the incoming argument into the field.'),
  ('mcq-java-constructors-and-this-vlar712ek1', 'java', 'Java Programming', 'constructors-and-this', 'oops', 'If a class defines only `Student(String name, int rollNumber)`, what happens with `new Student()`?', null, '[{"id":"a","text":"It compiles because Java always keeps a no-arg constructor available"},{"id":"b","text":"It compiles and uses default values"},{"id":"c","text":"It runs but prints null for name"},{"id":"d","text":"Compile error — no matching constructor"}]'::jsonb, 'd', 'Defining any constructor removes the automatically supplied no-arg default. Without a matching Student() defined explicitly, new Student() has nothing to call and fails to compile.'),
  ('mcq-java-constructors-and-this-1wsl80zalwj', 'java', 'Java Programming', 'constructors-and-this', 'oops', 'In a chained constructor, where must this(...) appear?', null, '[{"id":"a","text":"Anywhere in the constructor body"},{"id":"b","text":"It can''t be used inside a constructor"},{"id":"c","text":"As the very first statement"},{"id":"d","text":"As the very last statement"}]'::jsonb, 'c', 'Java requires an explicit constructor call via this(...) (or super(...)) to be the first statement, so the object''s other constructor logic runs before anything else in this one.'),
  ('mcq-java-static-120ap5gpq1s', 'java', 'Java Programming', 'static', 'oops', 'After three `new Student(...)` calls, each running `count++` on a static int count, what does Student.count read?', null, '[{"id":"a","text":"0"},{"id":"b","text":"3"},{"id":"c","text":"It depends on which object you check"},{"id":"d","text":"1"}]'::jsonb, 'b', 'count is static — one shared variable. All three constructor calls incremented the same field, so it correctly holds 3 regardless of which object (or the class name directly) you read it from.'),
  ('mcq-java-static-1zud5896qpp', 'java', 'Java Programming', 'static', 'oops', 'Why can''t a static method reference an instance field directly?', null, '[{"id":"a","text":"It is only a naming and style rule, and the compiler would accept the code with just a warning."},{"id":"b","text":"Instance fields are always private, and static methods can never see private members of their class."},{"id":"c","text":"It actually can: this is a myth, and a static method may read any instance field it can see."},{"id":"d","text":"A static method may run when no object exists yet, so there is no instance field for it to refer to."}]'::jsonb, 'd', 'A static method belongs to the class and can be called without any object existing. Instance fields only exist inside a specific object, so there''s nothing for the static method to reach without one being explicitly passed in.'),
  ('mcq-java-static-1drj8bflxdz', 'java', 'Java Programming', 'static', 'oops', 'Which of these is the conventionally correct way to access a static field named count on class Student?', null, '[{"id":"a","text":"count.Student"},{"id":"b","text":"Student->count"},{"id":"c","text":"Student.count"},{"id":"d","text":"s1.count where s1 is a Student object"}]'::jsonb, 'c', 'Static members belong to the class, so the class name is the correct, idiomatic way to access them — Student.count. Accessing it via an object reference compiles but is considered poor style.'),
  ('mcq-java-encapsulation-access-modifiers-1abqulyzve', 'java', 'Java Programming', 'encapsulation-access-modifiers', 'oops', 'What happens if code outside the BankAccount class writes `acc.balance = 5000;` where balance is private?', null, '[{"id":"a","text":"It works, and silently overwrites balance, because Java only warns about private access."},{"id":"b","text":"It fails to compile: private fields aren''t visible outside the class."},{"id":"c","text":"It works only if acc was itself declared public, which makes every field of it open."},{"id":"d","text":"It compiles but throws an exception at run time, when the private field is accessed."}]'::jsonb, 'b', 'private restricts visibility to code inside the same class. Any attempt to access the field directly from another class is a compile-time error, not a run-time one.'),
  ('mcq-java-encapsulation-access-modifiers-2dwq9m46r79', 'java', 'Java Programming', 'encapsulation-access-modifiers', 'oops', 'Which access modifier is applied when you write a field with no modifier keyword at all?', null, '[{"id":"a","text":"protected"},{"id":"b","text":"package-private (default)"},{"id":"c","text":"private"},{"id":"d","text":"public"}]'::jsonb, 'b', 'Omitting a modifier doesn''t mean private — it gives package-private access: visible to any class in the same package, but not outside it.'),
  ('mcq-java-encapsulation-access-modifiers-o1ixcnzqpe', 'java', 'Java Programming', 'encapsulation-access-modifiers', 'oops', 'Why does BankAccount provide deposit()/withdraw() methods instead of a plain setBalance(double) method?', null, '[{"id":"a","text":"setBalance would be slower than a method, because every setter call goes through extra JVM checks."},{"id":"b","text":"There''s no real difference, because a plain setter checks its argument automatically as well."},{"id":"c","text":"Methods can validate the change, rejecting negative deposits and overdrafts; a plain setter lets any value in."},{"id":"d","text":"Java doesn''t allow setter methods on double fields, so a differently named method is required."}]'::jsonb, 'c', 'The whole benefit of encapsulation is the chance to validate before a field changes. A generic setBalance would let any caller set any value, including invalid ones, bypassing the bank''s rules entirely.'),
  ('mcq-java-inheritance-and-super-y4wojcs8yd', 'java', 'Java Programming', 'inheritance-and-super', 'oops', 'What must be true for `super(name, baseSalary);` to be valid as the first line of Manager''s constructor?', null, '[{"id":"a","text":"Manager must also declare a field called baseSalary"},{"id":"b","text":"Nothing — super() always works regardless of the parent''s constructors"},{"id":"c","text":"Employee must be declared final"},{"id":"d","text":"Employee must have a matching constructor accepting (String, double)"}]'::jsonb, 'd', 'super(...) calls a specific constructor of the immediate superclass, matched by argument types, exactly like a normal constructor call — Employee must actually declare one with that signature.'),
  ('mcq-java-inheritance-and-super-27nmpcsin9p', 'java', 'Java Programming', 'inheritance-and-super', 'oops', 'Inside Manager''s overridden computePay(), what does `super.computePay()` return?', null, '[{"id":"a","text":"Manager''s own computePay() result, causing infinite recursion"},{"id":"b","text":"Employee''s original computePay(), i.e. just baseSalary"},{"id":"c","text":"0, because super methods can''t be called from an override"},{"id":"d","text":"It fails to compile, since the compiler insists that equals() and hashCode() are overridden together."}]'::jsonb, 'b', 'super.computePay() explicitly bypasses Manager''s own override and calls Employee''s version, returning baseSalary — that''s exactly why Manager can add teamBonus on top without duplicating the base salary logic.'),
  ('mcq-java-inheritance-and-super-1rtm028y7i3', 'java', 'Java Programming', 'inheritance-and-super', 'oops', 'Can a Java class extend more than one superclass directly, e.g. `class X extends A, B`?', null, '[{"id":"a","text":"Yes, Java fully supports this"},{"id":"b","text":"Only for abstract classes"},{"id":"c","text":"No — Java classes support only single inheritance"},{"id":"d","text":"Only if A and B share no methods"}]'::jsonb, 'c', 'Java deliberately disallows multiple class inheritance to avoid the ambiguity it can cause (e.g. two parents with conflicting methods). A class may extend only one superclass.'),
  ('mcq-java-polymorphism-27ouj40qnfo', 'java', 'Java Programming', 'polymorphism', 'oops', 'A Shape variable holds a Circle object. Calling shapeVar.area() runs whose area() — Shape''s or Circle''s?', null, '[{"id":"a","text":"Shape''s, because Java uses the variable''s declared type to choose which area() runs."},{"id":"b","text":"It depends on which class was compiled first, because Java picks the earlier-compiled version."},{"id":"c","text":"Circle''s, because Java picks the overridden method from the actual object at run time."},{"id":"d","text":"It fails to compile, because a Shape variable may not hold a Circle object."}]'::jsonb, 'c', 'Overriding is resolved dynamically — Java looks at what the object actually is at run time (Circle), not the declared type of the variable holding it (Shape), and runs Circle''s version.'),
  ('mcq-java-polymorphism-9kvr86sqft', 'java', 'Java Programming', 'polymorphism', 'oops', 'Two methods, `int calc(int a)` and `double calc(int a)`, differing only in return type — what happens?', null, '[{"id":"a","text":"Compile error — return type alone doesn''t distinguish a signature"},{"id":"b","text":"It compiles, but calling calc(5) is ambiguous at run time"},{"id":"c","text":"Valid overloading — Java picks based on the assignment target"},{"id":"d","text":"Valid overriding"}]'::jsonb, 'a', 'A method''s signature is its name plus parameter types — return type is not part of it. Two methods with the same name and parameter list but different return types is a straight compile error.'),
  ('mcq-java-polymorphism-1tfmb7bc7e', 'java', 'Java Programming', 'polymorphism', 'oops', 'Which is decided at compile time rather than run time?', null, '[{"id":"a","text":"Which overridden method a subclass object runs"},{"id":"b","text":"Both are decided at compile time"},{"id":"c","text":"Which overloaded method matches a given call"},{"id":"d","text":"Both are decided at run time"}]'::jsonb, 'c', 'Overload resolution is static — the compiler matches the call site''s argument types against available overloads before the program runs. Overriding, by contrast, is resolved dynamically, based on the actual object at run time.'),
  ('mcq-java-abstract-classes-and-interfaces-ztqxyhem25', 'java', 'Java Programming', 'abstract-classes-and-interfaces', 'oops', 'What happens if you write `new Vehicle("Test")` where Vehicle is declared abstract?', null, '[{"id":"a","text":"It works only if Vehicle has no constructor"},{"id":"b","text":"It compiles but throws an exception at run time"},{"id":"c","text":"Compile error — abstract classes cannot be instantiated directly"},{"id":"d","text":"It compiles and creates a Vehicle with fuelEfficiency() returning 0"}]'::jsonb, 'c', 'An abstract class may have unfinished (abstract) methods with no body, so Java disallows creating an instance of it directly — only a concrete subclass that fills in every abstract method can be instantiated.'),
  ('mcq-java-abstract-classes-and-interfaces-2g0n1dljom0', 'java', 'Java Programming', 'abstract-classes-and-interfaces', 'oops', 'A class needs to extend Vehicle and also promise Chargeable and, separately, Sellable behaviour. Is this possible?', null, '[{"id":"a","text":"Yes — extends one class, but implements any number of interfaces"},{"id":"b","text":"Only in Java 17 and later"},{"id":"c","text":"Only if Vehicle is also an interface"},{"id":"d","text":"No — a class can only extend or implement one type total"}]'::jsonb, 'a', 'Java allows single class inheritance (one extends) but multiple interface implementation (any number of implements) — exactly the combination ElectricCar uses with Vehicle and Chargeable.'),
  ('mcq-java-abstract-classes-and-interfaces-8he4n5lepc', 'java', 'Java Programming', 'abstract-classes-and-interfaces', 'oops', 'What is a default method on an interface?', null, '[{"id":"a","text":"A method with a body that implementing classes inherit unless they override it."},{"id":"b","text":"A method every implementing class must override, because interfaces cannot contain method bodies."},{"id":"c","text":"The interface''s constructor, which runs when a class that implements it is created."},{"id":"d","text":"A method that works only on primitive types, because defaults cannot take object parameters."}]'::jsonb, 'a', 'default methods (since Java 8) let an interface provide a working implementation. Implementing classes get it for free — printChargeStatus() runs unmodified for ElectricCar — but may override it if they need different behaviour.'),
  ('mcq-java-packages-1205tz8edl0', 'java', 'Java Programming', 'packages', 'oops', 'Where must MathUtils.java physically live if it declares `package com.school.util;`?', null, '[{"id":"a","text":"In a folder named exactly com/school/util/"},{"id":"b","text":"In a folder named util/"},{"id":"c","text":"Anywhere — package names are just labels with no folder requirement"},{"id":"d","text":"In the same folder as the class that imports it"}]'::jsonb, 'a', 'Java''s compiler and class loader require the folder path to mirror the package name exactly — com.school.util maps to the folder path com/school/util/, dots becoming path separators.'),
  ('mcq-java-packages-227zcxpcq98', 'java', 'Java Programming', 'packages', 'oops', 'Why does Main.java never need `import java.lang.System;` to use System.out.println?', null, '[{"id":"a","text":"println is a keyword, not a method"},{"id":"b","text":"It''s a compiler bug that happens to be convenient"},{"id":"c","text":"System isn''t really in a package"},{"id":"d","text":"java.lang is imported automatically into every Java file"}]'::jsonb, 'd', 'java.lang — which includes String, Math, System, and other fundamentals — is the one package Java imports into every file implicitly, so no explicit import line is ever needed for it.'),
  ('mcq-java-packages-s4m8g4hw0k', 'java', 'Java Programming', 'packages', 'oops', 'A package-private method in com.school.util.MathUtils — can com.school.app.Main call it, even after importing MathUtils?', null, '[{"id":"a","text":"Only if Main also declares package com.school.util at the top of its own file."},{"id":"b","text":"Yes, because the import gives Main full access to every method in MathUtils."},{"id":"c","text":"No: package-private access doesn''t extend to another package, whatever is imported."},{"id":"d","text":"Only if the method is static, since imports expose the static methods of other packages."}]'::jsonb, 'c', 'import only brings a class''s already-accessible members into scope by short name; it never widens access. A package-private member stays invisible outside its own package no matter what is imported.'),
  ('mcq-java-exceptions-831imxpifr', 'java', 'Java Programming', 'exceptions', 'oops', 'A method that can throw a checked exception without catching it — what must it do?', null, '[{"id":"a","text":"Nothing extra is required, because the compiler tracks checked exceptions on its own."},{"id":"b","text":"Rename the method so that it starts with the word throws, which marks it as risky."},{"id":"c","text":"Wrap the whole method body in try/catch, since a throws clause alone is never enough."},{"id":"d","text":"Declare throws ExceptionType in its signature, or the code fails to compile."}]'::jsonb, 'd', 'Checked exceptions are compiler-enforced: any method that doesn''t catch one must declare it with throws, or the code simply won''t compile — this is exactly what distinguishes checked from unchecked.'),
  ('mcq-java-exceptions-24ah8ouwskv', 'java', 'Java Programming', 'exceptions', 'oops', 'Does the finally block run if the try block''s exception is never caught by any matching catch?', null, '[{"id":"a","text":"Only when there''s no catch block at all, because otherwise the catch handles everything."},{"id":"b","text":"Only for checked exceptions, since unchecked ones skip the finally block entirely."},{"id":"c","text":"Yes: finally runs before the exception propagates further, whether or not it was caught."},{"id":"d","text":"No, finally runs only when the exception was caught by a catch block in the same method."}]'::jsonb, 'c', 'finally is guaranteed to run on the way out of a try block in virtually all cases, including when no catch clause matches and the exception is about to propagate up to the caller.'),
  ('mcq-java-exceptions-1gnzcbv4fq2', 'java', 'Java Programming', 'exceptions', 'oops', 'Which pair correctly matches checked vs unchecked?', null, '[{"id":"a","text":"Both are always checked"},{"id":"b","text":"Both are always unchecked"},{"id":"c","text":"NullPointerException is unchecked (extends RuntimeException); a custom exception extending Exception directly is checked"},{"id":"d","text":"NullPointerException is checked; a custom InsufficientBalanceException extends Exception is unchecked"}]'::jsonb, 'c', 'NullPointerException extends RuntimeException, making it unchecked. A custom exception that extends Exception directly (not RuntimeException) is checked, and the compiler will enforce handling it.'),
  ('mcq-java-wrapper-classes-autoboxing-ysemj9ztsk', 'java', 'Java Programming', 'wrapper-classes-autoboxing', 'oops', 'Why does `ArrayList<Integer>` work but `ArrayList<int>` fails to compile?', null, '[{"id":"a","text":"int is deprecated in recent Java versions, so the compiler rejects it wherever generics appear."},{"id":"b","text":"Primitive types can be stored only in arrays, never in any collection class, even through boxing."},{"id":"c","text":"Generics need an object type; Integer is int''s wrapper, and autoboxing converts between them automatically."},{"id":"d","text":"ArrayList can hold only Strings, so both versions fail unless the element type is String."}]'::jsonb, 'c', 'Java generics work only with reference (object) types, never primitives directly. Integer is the object wrapper for int, and autoboxing lets you write numbers where an Integer is expected without manual conversion.'),
  ('mcq-java-wrapper-classes-autoboxing-1nqx8qov1rh', 'java', 'Java Programming', 'wrapper-classes-autoboxing', 'oops', '`Integer x = 50; Integer y = 50;` — what does `x == y` evaluate to, and why?', null, '[{"id":"a","text":"true, because 50 falls in Java''s cached Integer range (-128 to 127)"},{"id":"b","text":"It fails to compile"},{"id":"c","text":"true, but only coincidentally with no defined reason"},{"id":"d","text":"false, because == never works on objects"}]'::jsonb, 'a', 'Java caches boxed Integer objects for values -128 to 127 as an optimisation, so both x and y point at the same cached object, making == true. This is implementation detail, not a guarantee to rely on.'),
  ('mcq-java-wrapper-classes-autoboxing-1eb1m13v980', 'java', 'Java Programming', 'wrapper-classes-autoboxing', 'oops', 'What happens when a null Integer is unboxed to a primitive int?', null, '[{"id":"a","text":"It becomes 0 silently"},{"id":"b","text":"It becomes -1"},{"id":"c","text":"It fails to compile"},{"id":"d","text":"It throws NullPointerException"}]'::jsonb, 'd', 'Unboxing calls .intValue() on the wrapper object behind the scenes. Calling any method on a null reference throws NullPointerException — there''s no silent fallback to 0.'),
  ('mcq-java-collections-overview-7aig4va03g', 'java', 'Java Programming', 'collections-overview', 'oops', 'Adding "Priya" twice to a List versus a Set — what''s the difference in the resulting size?', null, '[{"id":"a","text":"No difference: both grow by 2, because each add call always inserts a new element."},{"id":"b","text":"The Set grows by 2, while the List rejects the duplicate and grows by only 1."},{"id":"c","text":"Both throw an exception on the second add, because duplicate values are never legal in Java collections."},{"id":"d","text":"The List grows by 2, as duplicates are allowed; the Set grows by only 1, since the second add is ignored."}]'::jsonb, 'd', 'List explicitly permits duplicate elements, so both additions succeed. Set enforces uniqueness — adding an element already present does nothing, so the size only reflects one "Priya".'),
  ('mcq-java-collections-overview-k1y746ymia', 'java', 'Java Programming', 'collections-overview', 'oops', '`map.put("x", 1); map.put("x", 2);` — what is map.get("x") afterward, and how many entries does the map have?', null, '[{"id":"a","text":"It depends on the Map: HashMap keeps both values, while TreeMap keeps only one."},{"id":"b","text":"2, with 1 entry: the second put replaced the first value for the same key."},{"id":"c","text":"It throws an exception on the second put, because that key already exists."},{"id":"d","text":"1, with 2 entries, because put keeps the older value and stores the new one separately."}]'::jsonb, 'b', 'A Map allows only one value per key. The second put("x", 2) overwrites the first value rather than adding a new entry, so the map still has exactly one entry for key "x", now holding 2.'),
  ('mcq-java-collections-overview-1q7h9s508ze', 'java', 'Java Programming', 'collections-overview', 'oops', 'Which container would you choose to check quickly "has this roll number already been used?" with no need to keep insertion order?', null, '[{"id":"a","text":"Set<Integer>"},{"id":"b","text":"String"},{"id":"c","text":"A 2D array"},{"id":"d","text":"List<Integer>"}]'::jsonb, 'a', 'This is purely a membership question — exactly what Set is designed for, with fast contains() checks and automatic duplicate rejection, without needing order or a value attached to each entry.'),
  ('mcq-java-arraylist-vs-linkedlist-fh7uuvf878', 'java', 'Java Programming', 'arraylist-vs-linkedlist', 'oops', 'Which operation is fastest on an ArrayList compared to a LinkedList of the same size?', null, '[{"id":"a","text":"Inserting at the front"},{"id":"b","text":"They''re always equally fast"},{"id":"c","text":"Removing from the front"},{"id":"d","text":"get(index) — random access by position"}]'::jsonb, 'd', 'ArrayList stores elements contiguously, so get(index) jumps straight to that memory slot in constant time. LinkedList must walk node by node from the nearest end to reach that position.'),
  ('mcq-java-arraylist-vs-linkedlist-1xalkp4kuxx', 'java', 'Java Programming', 'arraylist-vs-linkedlist', 'oops', 'Why does `arrayList.add(1, "Neha")` cost more as the list grows larger?', null, '[{"id":"a","text":"ArrayList has to sort itself again after every insert, and sorting grows with the size."},{"id":"b","text":"It doesn''t cost more: inserting into an ArrayList always takes constant time."},{"id":"c","text":"Every element from index 1 onward has to shift one position to make room."},{"id":"d","text":"It only costs more if the list contains duplicate values that must be compared first."}]'::jsonb, 'c', 'Inserting anywhere but the end of an ArrayList requires shifting every subsequent element one slot over, an amount of work proportional to how many elements come after the insertion point.'),
  ('mcq-java-arraylist-vs-linkedlist-25fgfnablve', 'java', 'Java Programming', 'arraylist-vs-linkedlist', 'oops', 'You need a structure that frequently adds and removes elements from both the front and back, and rarely looks up by index. Which fits better?', null, '[{"id":"a","text":"ArrayList"},{"id":"b","text":"Neither — use a String"},{"id":"c","text":"A plain array"},{"id":"d","text":"LinkedList"}]'::jsonb, 'd', 'LinkedList''s doubly linked structure makes adding/removing at either end cheap (constant time), which is exactly the access pattern described — random access by index is explicitly not the priority here.'),
  ('mcq-java-hashmap-and-hashset-1nw6lf6w1pz', 'java', 'Java Programming', 'hashmap-and-hashset', 'oops', 'A class overrides equals() to compare by value but never overrides hashCode(). What''s the practical effect on a HashSet of that class?', null, '[{"id":"a","text":"It fails to compile"},{"id":"b","text":"HashSet automatically generates a matching hashCode() from the fields that equals() compares."},{"id":"c","text":"Equal objects may land in different buckets and never get compared, so they''re treated as distinct."},{"id":"d","text":"It works fine, because HashSet compares every pair of elements using equals() alone."}]'::jsonb, 'c', 'hashCode() decides which bucket an object goes in; equals() is only checked between objects that land in the same bucket. Without a matching hashCode() override, equal objects can hash differently and never be compared at all, breaking deduplication.'),
  ('mcq-java-hashmap-and-hashset-10h2lxmt05', 'java', 'Java Programming', 'hashmap-and-hashset', 'oops', 'What does `wordCount.get("dog")` return if "dog" was never put into the map?', null, '[{"id":"a","text":"It throws NoSuchElementException"},{"id":"b","text":"-1"},{"id":"c","text":"0"},{"id":"d","text":"null"}]'::jsonb, 'd', 'A HashMap lookup for a key that was never inserted returns null, not an exception and not a default numeric value — this is exactly why getOrDefault exists, to supply a fallback in one call.'),
  ('mcq-java-hashmap-and-hashset-15xmcvemcto', 'java', 'Java Programming', 'hashmap-and-hashset', 'oops', 'What is `Objects.hash(x, y)` used for in the Point class?', null, '[{"id":"a","text":"To sort a list of Points by their hash values, so equal points sit side by side."},{"id":"b","text":"To compare two Points for equality directly, field by field, without calling equals()."},{"id":"c","text":"It''s unrelated to hashing despite the name; it only builds a string from the fields."},{"id":"d","text":"To produce one combined hash code from several fields, consistent with equals()."}]'::jsonb, 'd', 'Objects.hash(...) is a standard library helper that combines several fields into one hash code — using the same fields equals() compares is exactly what keeps the two methods consistent with each other.'),
  ('mcq-java-generics-1fcvxzqkinm', 'java', 'Java Programming', 'generics', 'oops', 'What is the main advantage of `Box<T>` over an older design storing `Object content`?', null, '[{"id":"a","text":"There is no real difference, because both designs report type errors at the same stage."},{"id":"b","text":"Type mismatches are caught at compile time instead of failing later with a ClassCastException."},{"id":"c","text":"Box<T> runs faster, because the compiler generates a separate optimised copy for each type."},{"id":"d","text":"Box<T> uses less memory, because the compiler removes the object header from every stored value."}]'::jsonb, 'b', 'With Object, retrieving a value requires an unchecked cast that can fail at run time if the wrong type was stored. Generics let the compiler enforce the correct type at every call site, catching the mistake before the program runs.'),
  ('mcq-java-generics-euu1mlbyw8', 'java', 'Java Programming', 'generics', 'oops', 'Can a generic class have more than one type parameter, like Pair<K, V>?', null, '[{"id":"a","text":"Yes — a class can declare as many type parameters as needed"},{"id":"b","text":"No, Java generics allow exactly one type parameter per class"},{"id":"c","text":"Only for interfaces, never classes"},{"id":"d","text":"Only if both parameters are the same type"}]'::jsonb, 'a', 'Generic classes can declare any number of type parameters, separated by commas — Pair<K, V> uses two independent ones, which don''t need to be related types at all.'),
  ('mcq-java-generics-2dqv4jcayu7', 'java', 'Java Programming', 'generics', 'oops', 'Why can''t you write `new T()` directly inside a generic class like Box<T>?', null, '[{"id":"a","text":"T can be used only for method parameters, never for creating objects of any kind."},{"id":"b","text":"You actually can write it, and the claim that you can''t is a common myth."},{"id":"c","text":"It''s just a style convention, and the compiler would accept it with only a warning."},{"id":"d","text":"Java erases generic type information at run time, so T isn''t a type it can instantiate."}]'::jsonb, 'd', 'Java uses type erasure: generic type parameters exist for compile-time checking but are erased from the actual bytecode. At run time there''s no real T to call new on directly without extra help (like passing a Class<T> reference).'),
  ('mcq-java-comparable-and-comparator-1hzcvhffy6v', 'java', 'Java Programming', 'comparable-and-comparator', 'oops', 'Calling `Collections.sort(students)` with no second argument requires what of the Student class?', null, '[{"id":"a","text":"Student must implement Comparable and define compareTo()"},{"id":"b","text":"Student must be declared final"},{"id":"c","text":"Student must override equals() only"},{"id":"d","text":"Nothing special — it always works"}]'::jsonb, 'a', 'The no-argument overload of Collections.sort relies on the elements'' natural ordering, which requires the class to implement Comparable and provide a compareTo() method — without it, this call doesn''t compile for a typed List<Student>.'),
  ('mcq-java-comparable-and-comparator-1gsin0t0oib', 'java', 'Java Programming', 'comparable-and-comparator', 'oops', 'You need to sort the same List<Student> by marks in one place and by name in another, without changing the Student class. What''s the right tool?', null, '[{"id":"a","text":"This isn''t possible in Java"},{"id":"b","text":"Use two different Comparators, one per ordering, passed to list.sort()"},{"id":"c","text":"Rewrite compareTo() each time you need a different order"},{"id":"d","text":"Implement Comparable twice, differently, in each place"}]'::jsonb, 'b', 'Comparator is exactly the tool for multiple, situational orderings defined outside the class — you can write as many as you need without ever touching Student or its single Comparable ordering.'),
  ('mcq-java-comparable-and-comparator-11cvhpwbjfu', 'java', 'Java Programming', 'comparable-and-comparator', 'oops', 'Why is `Integer.compare(this.marks, other.marks)` generally preferred over `this.marks - other.marks` inside compareTo()?', null, '[{"id":"a","text":"Subtraction is not allowed inside compareTo, so Integer.compare is the only version that compiles."},{"id":"b","text":"There''s no real difference; both versions return the same sign for every possible pair of ints."},{"id":"c","text":"Subtraction doesn''t work on int values at all, so it has to be replaced with a method call."},{"id":"d","text":"Subtraction can overflow for extreme int values and give the wrong sign; Integer.compare avoids that."}]'::jsonb, 'd', 'If marks were near Integer.MIN_VALUE/MAX_VALUE (unrealistic for exam marks, but a real risk in general), subtraction can overflow and flip the sign, giving a wrong ordering. Integer.compare is always correct regardless of the values involved.'),
  ('mcq-java-file-io-287hkw0ptzx', 'java', 'Java Programming', 'file-io', 'oops', 'What happens when Files.write(file, lines) is called a second time on the same file, with no APPEND option?', null, '[{"id":"a","text":"It throws an exception because the file already exists"},{"id":"b","text":"The file''s previous content is overwritten entirely by the new content"},{"id":"c","text":"Both writes are merged line by line"},{"id":"d","text":"The new content is added after the existing content"}]'::jsonb, 'b', 'Files.write defaults to overwriting the file''s contents. Without explicitly passing StandardOpenOption.APPEND, a second write replaces everything the first write put there.'),
  ('mcq-java-file-io-1yzkqmz8l1j', 'java', 'Java Programming', 'file-io', 'oops', 'Why must a method calling Files.readAllLines either catch IOException or declare `throws IOException`?', null, '[{"id":"a","text":"This is true only on Windows, where file access can fail; other systems never throw it."},{"id":"b","text":"readAllLines never actually throws anything, so the try/catch would always be unnecessary."},{"id":"c","text":"It''s an optional style choice, and the code compiles whether or not the exception is handled."},{"id":"d","text":"IOException is a checked exception, so the compiler forces you to handle or declare it."}]'::jsonb, 'd', 'File operations can fail for reasons outside the program''s control (missing file, permissions, disk issues), so Java models them with the checked IOException, which the compiler requires you to handle or propagate.'),
  ('mcq-java-file-io-140frikwt9v', 'java', 'Java Programming', 'file-io', 'oops', 'Parsing "Vikram,78" with `line.split(",")`, what is `parts[1]`?', null, '[{"id":"a","text":"\"Vikram,78\""},{"id":"b","text":"\"78\""},{"id":"c","text":"78 as an int, directly"},{"id":"d","text":"\"Vikram\""}]'::jsonb, 'b', 'split(",") breaks the string at each comma into an array: ["Vikram", "78"]. parts[1] is the second element, the string "78" — still text, which is why Integer.parseInt is needed to use it as a number.'),
  ('mcq-java-stack-heap-gc-60mxmikmtg', 'java', 'Java Programming', 'stack-heap-gc', 'oops', 'Where do a method''s local int variables live while the method is executing?', null, '[{"id":"a","text":"The stack, in that method''s own frame"},{"id":"b","text":"Neither — they don''t exist in memory"},{"id":"c","text":"The heap"},{"id":"d","text":"Wherever the JVM''s garbage collector puts them"}]'::jsonb, 'a', 'Local variables and parameters live in the stack frame created for that specific method call, and that frame is popped and cleared automatically the instant the method returns.'),
  ('mcq-java-stack-heap-gc-1rysdhgbblt', 'java', 'Java Programming', 'stack-heap-gc', 'oops', 'After `first = null; reference1 = null;` while reference2 still points at the same Node, is that Node eligible for garbage collection?', null, '[{"id":"a","text":"No: reference2 still reaches it, so it stays reachable and ineligible for collection."},{"id":"b","text":"It depends on when System.gc() is called, since eligibility is decided only at that moment."},{"id":"c","text":"Yes, because two of the three references to it are now null, leaving it mostly unused."},{"id":"d","text":"Yes, immediately, because assigning null to a reference frees the object it pointed to."}]'::jsonb, 'a', 'An object becomes eligible for garbage collection only once nothing in the program can reach it anymore. reference2 is still a live path to that Node, so it''s still reachable and safe from collection.'),
  ('mcq-java-stack-heap-gc-sybg560d9h', 'java', 'Java Programming', 'stack-heap-gc', 'oops', 'What does calling `System.gc()` actually guarantee?', null, '[{"id":"a","text":"That every local variable in the current method is cleared back to its default value."},{"id":"b","text":"That garbage collection runs immediately and every unreachable object is freed before the call returns."},{"id":"c","text":"Nothing specific; it is only a hint to the JVM, which may or may not act on it soon."},{"id":"d","text":"That the program will crash with an OutOfMemoryError if any objects are still reachable."}]'::jsonb, 'c', 'System.gc() only requests that the JVM consider running garbage collection — it is not a command, and the JVM is free to delay or effectively ignore it depending on its own memory management strategy.'),
  ('mcq-java-multithreading-basics-1jw0jv77twe', 'java', 'Java Programming', 'multithreading-basics', 'oops', 'What''s the difference between calling thread.start() and thread.run() directly?', null, '[{"id":"a","text":"No difference: both create a new thread, and run() is simply the older name for start()."},{"id":"b","text":"start() launches the code on a new thread; run() just executes it on the current thread, with no concurrency."},{"id":"c","text":"run() is the method that creates the new thread, and start() just runs the code on the current one."},{"id":"d","text":"start() can be called only once per program, so a second thread must be launched with run() instead."}]'::jsonb, 'b', 'start() is what actually creates and launches a new thread of execution. Calling run() directly just invokes that method like any other, on whichever thread called it — no new thread involved at all.'),
  ('mcq-java-multithreading-basics-2b1ebpx4db', 'java', 'Java Programming', 'multithreading-basics', 'oops', 'Two threads both run `count++` on the same unsynchronized int field, 1000 times each. What''s the safest expectation for the final count?', null, '[{"id":"a","text":"Always exactly 1000, because the second thread''s updates simply overwrite those of the first."},{"id":"b","text":"Possibly less than 2000, because count++ isn''t atomic and some increments can be lost."},{"id":"c","text":"It throws a ConcurrentModificationException, because two threads touch the same field at once."},{"id":"d","text":"Always exactly 2000, because each count++ is a single step that can never be interrupted."}]'::jsonb, 'b', 'count++ is really read-add-write. Without synchronization, two threads can interleave those steps and lose an increment, so the final total can unpredictably come out below 2000 — this is the textbook race condition.'),
  ('mcq-java-multithreading-basics-12kk461k9s7', 'java', 'Java Programming', 'multithreading-basics', 'oops', 'What does calling t1.join() in the main thread do?', null, '[{"id":"a","text":"Merges t1''s memory with main''s, so both threads then share the same variables."},{"id":"b","text":"Stops t1 immediately, so that main can carry on without waiting for it."},{"id":"c","text":"Starts t1 running, so that it begins work alongside the main thread."},{"id":"d","text":"Makes main wait until t1 has finished before it continues."}]'::jsonb, 'd', 'join() blocks the calling thread (here, main) until the thread it''s called on (t1) completes. It''s the standard way to guarantee ordering between threads instead of leaving it to the scheduler.'),
  ('mcq-java-lambdas-functional-interfaces-2byxwtg3hc7', 'java', 'Java Programming', 'lambdas-functional-interfaces', 'oops', 'Which of these can a lambda expression be assigned to?', null, '[{"id":"a","text":"Only an interface with exactly one abstract method (a functional interface)."},{"id":"b","text":"Any interface at all, as long as the lambda''s parameters match one of its methods."},{"id":"c","text":"Only interfaces from the java.util.function package, and no interface that you write yourself."},{"id":"d","text":"Any class, as long as the lambda is placed inside one of that class''s methods."}]'::jsonb, 'a', 'A lambda''s body provides the implementation for exactly one method, so it can only stand in for a functional interface — one with a single abstract method — not an arbitrary interface or class.'),
  ('mcq-java-lambdas-functional-interfaces-2cnkoe2btef', 'java', 'Java Programming', 'lambdas-functional-interfaces', 'oops', 'Given `Function<Integer, Integer> square = n -> n * n;`, what does `applyTwice(square, 3)` (calling f.apply(f.apply(start))) return?', null, '[{"id":"a","text":"6"},{"id":"b","text":"18"},{"id":"c","text":"9"},{"id":"d","text":"81"}]'::jsonb, 'd', 'square is applied twice, chained: first 3*3=9, then that result squared again, 9*9=81 — not 3 squared once, and not doubled.'),
  ('mcq-java-lambdas-functional-interfaces-118s1hywbbw', 'java', 'Java Programming', 'lambdas-functional-interfaces', 'oops', 'Which java.util.function interface fits "take one Integer, return true or false"?', null, '[{"id":"a","text":"Runnable"},{"id":"b","text":"Function<Integer, Integer>"},{"id":"c","text":"Predicate<Integer>"},{"id":"d","text":"BiFunction<Integer, Integer, Boolean>"}]'::jsonb, 'c', 'Predicate<T> is specifically shaped for exactly this: one input of type T, a boolean result via test(T) — the standard interface for filtering/testing conditions.'),
  ('mcq-java-streams-api-lk9r61gic4', 'java', 'Java Programming', 'streams-api', 'oops', 'In a stream pipeline `.filter(...).map(...).sorted()` with no terminal operation, what happens?', null, '[{"id":"a","text":"Nothing runs yet; streams are lazy until a terminal operation like collect() or count() is called."},{"id":"b","text":"It throws a compile error, because every stream pipeline must end with a terminal operation."},{"id":"c","text":"It runs filter and map straight away, but sorted waits until a terminal operation arrives."},{"id":"d","text":"It runs immediately, because filter, map and sorted each do their work as soon as they are called."}]'::jsonb, 'a', 'Intermediate operations only describe the pipeline; none of them actually execute until a terminal operation is invoked, at which point the whole chain runs once per element.'),
  ('mcq-java-streams-api-a9w96k9rfv', 'java', 'Java Programming', 'streams-api', 'oops', 'What''s the key difference between .map(...) and .filter(...) on a stream?', null, '[{"id":"a","text":"map transforms every element into something else; filter removes the elements that fail a condition."},{"id":"b","text":"They''re interchangeable, since both pass each element through a function and keep the result."},{"id":"c","text":"filter transforms every element into a new value, while map removes elements that fail a condition."},{"id":"d","text":"map only works on numbers, while filter can be used on any type of element."}]'::jsonb, 'a', 'map applies a transformation to every element and passes all of them onward, possibly changed. filter tests each element against a condition and only lets the matching ones through, unchanged.'),
  ('mcq-java-streams-api-hmou7yrhdc', 'java', 'Java Programming', 'streams-api', 'oops', 'Given the toppers pipeline (filter marks >= 80, map to name, sorted), which student is excluded from the final result and why?', null, '[{"id":"a","text":"Arjun, because the alphabetical sorting step drops the name that comes first."},{"id":"b","text":"No one is excluded, because filter only reorders the students and never removes any."},{"id":"c","text":"Neha, because her marks are too high to fit in a list of the toppers."},{"id":"d","text":"Vikram (78) and Rahul (62), as both fail the marks >= 80 filter."}]'::jsonb, 'd', 'The filter step keeps only students with marks >= 80. Vikram (78) and Rahul (62) both fall below that threshold and are removed before map or sorted ever sees them.'),
  ('mcq-java-records-modern-java-11jfcwejhmp', 'java', 'Java Programming', 'records-modern-java', 'oops', 'Why is p1.equals(p2) true for two separately created `new Point(3, 4)` records?', null, '[{"id":"a","text":"Only because == was actually used in that comparison, rather than the equals() method."},{"id":"b","text":"It isn''t true: records always compare by identity, like ordinary objects created with new."},{"id":"c","text":"Because Java caches Point objects like small Integers, so both variables share one object."},{"id":"d","text":"Records automatically generate equals() and hashCode() that compare their components by value."}]'::jsonb, 'd', 'A record''s compiler-generated equals() compares all of its declared components by value, unlike the identity-based default Object.equals() an ordinary class would have without an explicit override.'),
  ('mcq-java-records-modern-java-aotuon5tnt', 'java', 'Java Programming', 'records-modern-java', 'oops', 'What does declaring `sealed interface Shape permits Circle, Rectangle {}` enable?', null, '[{"id":"a","text":"It stops Circle and Rectangle from being records, because sealed types may only be ordinary classes."},{"id":"b","text":"Nothing beyond documentation: the compiler ignores permits, and any other class may still implement Shape."},{"id":"c","text":"The compiler knows Circle and Rectangle are the only Shape subtypes, so a switch can be exhaustive with no default."},{"id":"d","text":"It makes every method of Shape automatically final, so Circle and Rectangle cannot override them."}]'::jsonb, 'c', 'sealed restricts which types may implement Shape to the explicitly permitted list. This lets the compiler verify a switch over Shape covers every possible case, without needing a fallback default arm.'),
  ('mcq-java-records-modern-java-1bw3u4bn6ip', 'java', 'Java Programming', 'records-modern-java', 'oops', 'Is `var message = "hello";` dynamically typed — can message later be reassigned to hold an int?', null, '[{"id":"a","text":"Yes, var lets the variable''s type change whenever a value of another type is assigned."},{"id":"b","text":"Yes, but only for local variables inside a method; fields declared with var keep a fixed type."},{"id":"c","text":"No, var infers the type once at compile time; message stays a String, and assigning an int is a compile error."},{"id":"d","text":"It depends on the JVM version, since older runtimes treated var as a dynamic type."}]'::jsonb, 'c', 'var is purely a compile-time convenience for omitting an explicit type when it''s inferable. The variable''s type is fixed at that point, exactly as if the type had been written out, so message = 5; afterward would be a compile error.'),
  ('mcq-javascript-what-is-javascript-1fl0u8hxv1c', 'javascript', 'JavaScript, React and Node', 'what-is-javascript', null, 'Which of these is provided by the runtime, not by the JavaScript language itself?', null, '[{"id":"a","text":"`Array.prototype.map`"},{"id":"b","text":"`setTimeout`"},{"id":"c","text":"`let`"},{"id":"d","text":"`Promise`"}]'::jsonb, 'b', '`map`, `Promise` and `let` are all defined in the ECMAScript standard. `setTimeout` is supplied by the browser or by Node.'),
  ('mcq-javascript-what-is-javascript-1xei2xuf4rz', 'javascript', 'JavaScript, React and Node', 'what-is-javascript', null, 'What does `console.log("4" + 1)` print?', null, '[{"id":"a","text":"5"},{"id":"b","text":"It throws an error"},{"id":"c","text":"41"},{"id":"d","text":"NaN"}]'::jsonb, 'c', 'When one side of `+` is a string, the other side is converted to text and the two are joined, so you get the text 41. Chapter 3 covers the rule.'),
  ('mcq-javascript-what-is-javascript-1lx1s1v4n2y', 'javascript', 'JavaScript, React and Node', 'what-is-javascript', null, 'A teammate says "V8 is JavaScript". What is the most accurate correction?', null, '[{"id":"a","text":"V8 is a library for the DOM."},{"id":"b","text":"V8 is an engine that runs JavaScript; Node and Chrome both embed it."},{"id":"c","text":"V8 is the language specification."},{"id":"d","text":"V8 is a browser."}]'::jsonb, 'b', 'V8 is an engine: it reads and runs JavaScript. Chrome and Node.js wrap it in different runtimes.'),
  ('mcq-javascript-values-and-variables-nz83knc08w', 'javascript', 'JavaScript, React and Node', 'values-and-variables', null, 'What does this print?

const nums = [1, 2];
nums.push(3);
console.log(nums.length);', null, '[{"id":"a","text":"It throws a TypeError because nums is const"},{"id":"b","text":"2"},{"id":"c","text":"undefined"},{"id":"d","text":"3"}]'::jsonb, 'd', 'const only stops `nums = something else`. push changes the array''s contents, which is allowed, so the length is 3.'),
  ('mcq-javascript-values-and-variables-1upgsb6idyb', 'javascript', 'JavaScript, React and Node', 'values-and-variables', null, 'What does `console.log(typeof typeof 1)` print?', null, '[{"id":"a","text":"\"number\""},{"id":"b","text":"\"object\""},{"id":"c","text":"\"undefined\""},{"id":"d","text":"\"string\""}]'::jsonb, 'd', '`typeof 1` is the string "number", and `typeof` of any string is "string". `typeof` always returns a string.'),
  ('mcq-javascript-values-and-variables-1rzcjp5r3ta', 'javascript', 'JavaScript, React and Node', 'values-and-variables', null, 'Which statement about `typeof null` is correct?', null, '[{"id":"a","text":"It is \"null\", because null is its own type."},{"id":"b","text":"It is \"undefined\"."},{"id":"c","text":"It is \"object\", a long-standing quirk kept for compatibility."},{"id":"d","text":"It throws a TypeError."}]'::jsonb, 'c', 'The answer "object" comes from an early implementation mistake. Fixing it would have broken existing websites.'),
  ('mcq-javascript-operators-and-coercion-t48gr9bw1r', 'javascript', 'JavaScript, React and Node', 'operators-and-coercion', null, 'What does this print?

console.log("3" + 4 + 5);
console.log(3 + 4 + "5");', null, '[{"id":"a","text":"\"345\" then \"345\""},{"id":"b","text":"\"12\" then \"75\""},{"id":"c","text":"\"345\" then \"75\""},{"id":"d","text":"\"75\" then \"345\""}]'::jsonb, 'c', 'Evaluation is left to right. In the first line, "3" + 4 is already text ("34"), then "34" + 5 is "345". In the second, 3 + 4 is the number 7, then 7 + "5" is "75".'),
  ('mcq-javascript-operators-and-coercion-2fbt7p3tama', 'javascript', 'JavaScript, React and Node', 'operators-and-coercion', null, 'What does `null ?? "x" || "y"` evaluate to... or does it fail?', null, '[{"id":"a","text":"\"y\""},{"id":"b","text":"null"},{"id":"c","text":"A SyntaxError"},{"id":"d","text":"\"x\""}]'::jsonb, 'c', 'Mixing `??` with `||` or `&&` without parentheses is a SyntaxError by design, so you must say which one groups first.'),
  ('mcq-javascript-operators-and-coercion-28g7cp8js3h', 'javascript', 'JavaScript, React and Node', 'operators-and-coercion', null, 'Which expression is true?', null, '[{"id":"a","text":"`null == undefined`"},{"id":"b","text":"`null == 0`"},{"id":"c","text":"`[] === []`"},{"id":"d","text":"`NaN == NaN`"}]'::jsonb, 'a', 'null and undefined equal each other under ==. NaN is never equal to itself. null does not equal 0 under ==. Two separate arrays are two different objects, so === is false.'),
  ('mcq-javascript-control-flow-2apqtuxwrgl', 'javascript', 'JavaScript, React and Node', 'control-flow', null, 'What does this print?

for (let i = 0; i < 5; i++) {
  if (i % 2 === 0) continue;
  console.log(i);
}', null, '[{"id":"a","text":"1 3"},{"id":"b","text":"1 2 3 4"},{"id":"c","text":"0 1 2 3 4"},{"id":"d","text":"0 2 4"}]'::jsonb, 'a', 'continue skips the rest of the body when i is even, so only the odd values 1 and 3 are logged.'),
